  ('m1', 'r1', 'c1', 'Paneer Biryani', 'Fragrant basmati rice layered with marinated paneer and whole spices.', 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=600&q=80', 220, 'veg', 4.4, true, '[{"id":"og1","name":"Size","required":true,"options":[{"id":"opt1","label":"Regular","priceDelta":0},{"id":"opt2","label":"Large","priceDelta":60}]}]'::jsonb, '[{"id":"a1","name":"Extra Paneer","priceDelta":40},{"id":"a2","name":"Raita","priceDelta":25}]'::jsonb, true, true),
  ('m2', 'r1', 'c1', 'Chicken Dum Biryani', 'Slow-cooked chicken biryani sealed and steamed with saffron and fried onions.', 'https://images.unsplash.com/photo-1476224203421-9ac39bcb3327?auto=format&fit=crop&w=600&q=80', 260, 'non-veg', 4.6, true, '[{"id":"og2","name":"Portion","required":true,"options":[{"id":"opt3","label":"Half","priceDelta":0},{"id":"opt4","label":"Full","priceDelta":90}]}]'::jsonb, '[{"id":"a3","name":"Extra Egg","priceDelta":20},{"id":"a4","name":"Raita","priceDelta":25}]'::jsonb, true, true),
